const normalizarAreaGestao = (valor, perfil = '') => {
  if (String(perfil || '').toLowerCase() === 'admin') {
    return 'AMBOS';
  }

  const area = String(valor || '').trim().toUpperCase();
  return ['VD', 'LOJA', 'AMBOS'].includes(area)
    ? area
    : 'AMBOS';
};

